import argparse,hashlib,json,time,subprocess
import numpy as np
import torch
from run_unlearning import ROOT,load_data,graph,ODSR,seed_everything,digest,evaluate,atomic_json
from social_unlearning.gnndelete_social import train_deletion

def run(a):
 torch.set_num_threads(4);device=torch.device(a.device);seed_everything(a.seed);raw=load_data(a.dataset,a.seed);base=ROOT/'checkpoints/ODSR'/a.dataset/f'seed_{a.seed}'/raw.meta['split_hash'][:16];ck=torch.load(base/'original/deployment.pt',map_location=device,weights_only=False);cfg=ck['config'];original=ODSR(graph(raw,np.arange(raw.U),device),cfg,device).to(device);original.load_state_dict(ck['model']);deleted=np.sort(np.random.default_rng(a.seed+10000).permutation(raw.U)[:max(1,round(raw.U*a.fraction))]);dh=digest(deleted);directory=ROOT/'checkpoints/baselines/GNNDelete_social'/a.dataset/f'seed_{a.seed}'/raw.meta['split_hash'][:16]/dh[:16]
 if (directory/'results.json').exists() and (directory/'deployment.pt').exists():print('REUSE_GNNDELETE '+str(directory));return
 source=ROOT/'external/baseline_sources/GNNDelete';prov=dict(original=ck['provenance'],deletion=dh,adapter=hashlib.sha256((ROOT/'src/social_unlearning/gnndelete_social.py').read_bytes()).hexdigest(),official_commit=subprocess.check_output(['git','-C',str(source),'rev-parse','HEAD'],text=True).strip(),max_steps=a.steps)
 torch.cuda.synchronize(device);torch.cuda.reset_peak_memory_stats(device);start=time.perf_counter();data=graph(raw,np.setdiff1d(np.arange(raw.U),deleted),device);model,training=train_deletion(original,raw,data,cfg,directory,device,a.seed,prov,a.steps);torch.cuda.synchronize(device);wall=time.perf_counter()-start;peak=torch.cuda.max_memory_allocated(device);refck=torch.load(base/dh[:16]/'random/retrain/deployment.pt',map_location=device,weights_only=False);reference=ODSR(data,cfg,device).to(device);reference.load_state_dict(refck['model']);_,ref=evaluate(reference,data,data.test,device);metrics,_=evaluate(model,data,data.test,device,reference=ref)
 atomic_json(directory/'results.json',dict(status='completed_source_operator_social_adaptation',method='GNNDelete_social',dataset=a.dataset,seed=a.seed,fraction=a.fraction,metrics=metrics,provenance=prov,training=training,efficiency=dict(total_deletion_seconds=wall,peak_allocated_bytes=peak,timing_mode='throughput_shared_server'),mia_status='pending',adaptation='Official DeletionLayer; three ODSR layers and social-state transformation; typed negative pairs; DEC/NI node-embedding MSE with source-supported joint loss alpha=.5; original-graph request witnesses; compact retained deployment; lr=.001, validation every25 steps, patience10, cap1500. Not an unchanged original-method reproduction.'))
 print('GNNDELETE_RESULT '+str(directory/'results.json'),flush=True)
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--dataset',default='epinions');p.add_argument('--seed',type=int,required=True);p.add_argument('--fraction',type=float,default=.01);p.add_argument('--device',default='cuda:0');p.add_argument('--steps',type=int,default=1500);run(p.parse_args())
